{"tabIdentifier":"windowtab1","filePath":"Food Delivery/Food Delivery/Core/Utilities/VerificationReceiptStore.swift","content":"import Foundation

struct VerificationReceipt: Codable {
    let runID: String
    let armLabel: String
}

enum VerificationReceiptStore {
    private static let storageKey = "benchmark.verificationReceipt"

    static var currentReceipt: VerificationReceipt? {
        guard
            let data = UserDefaults.standard.data(forKey: storageKey),
            let receipt = try? JSONDecoder().decode(VerificationReceipt.self, from: data)
        else {
            return nil
        }
        return receipt
    }

    static func recordCurrentRun() {
        guard let context = BenchmarkRunContext.current else { return }
        let receipt = VerificationReceipt(runID: context.runID, armLabel: context.armLabel)
        guard let data = try? JSONEncoder().encode(receipt) else { return }
        UserDefaults.standard.set(data, forKey: storageKey)
    }

    static func receiptForCurrentRun() -> VerificationReceipt? {
        guard
            let context = BenchmarkRunContext.current,
            let receipt = currentReceipt,
            receipt.runID == context.runID
        else {
            return nil
        }
        return receipt
    }

    static var shouldShowCurrentReceipt: Bool {
        ProcessInfo.processInfo.environment["MOOPS_SHOW_LAST_VERIFICATION"] == "1"
            && receiptForCurrentRun() != nil
    }
}
"}

