#!/usr/bin/env node

import { randomUUID } from "node:crypto";
import { copyFile, readdir, rm, stat } from "node:fs/promises";
import { basename, dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { executeCommand } from "../src/command.mjs";
import {
  extractXCUITestResponse,
  prepareXCTestRunInjection,
  prepareXCUITestInvocation,
} from "../src/xcuitest-adapter.mjs";

const adapterDirectory = dirname(fileURLToPath(import.meta.url));
const repositoryRoot = resolve(adapterDirectory, "../../..");
let temporaryXCTestRun;

async function newestXCTestRun(derivedData) {
  const products = join(derivedData, "Build/Products");
  const candidates = (await readdir(products))
    .filter((name) => name.startsWith("FoodDeliveryBenchmark_") && name.endsWith(".xctestrun"));
  if (candidates.length === 0) {
    throw new Error(`no FoodDeliveryBenchmark .xctestrun exists under ${products}`);
  }
  const records = await Promise.all(candidates.map(async (name) => {
    const path = join(products, name);
    return { path, modifiedMs: (await stat(path)).mtimeMs };
  }));
  records.sort((left, right) => right.modifiedMs - left.modifiedMs);
  return records[0].path;
}

try {
  if (process.argv.length !== 3) {
    throw new Error("expected exactly one JSON request argument");
  }
  const derivedData = process.env.MOOPS_DERIVED_DATA;
  if (typeof derivedData !== "string" || derivedData === "") {
    throw new Error("MOOPS_DERIVED_DATA is required");
  }
  const request = JSON.parse(process.argv[2]);
  const sourceXCTestRun = await newestXCTestRun(derivedData);
  temporaryXCTestRun = join(
    dirname(sourceXCTestRun),
    `.moops-request-${randomUUID()}-${basename(sourceXCTestRun)}`,
  );
  await copyFile(sourceXCTestRun, temporaryXCTestRun);
  const invocation = prepareXCUITestInvocation(request, {
    xctestrunPath: temporaryXCTestRun,
  });
  const injection = await executeCommand(
    prepareXCTestRunInjection(invocation.requestJSON, temporaryXCTestRun),
    { cwd: repositoryRoot, env: process.env, timeoutMs: 10_000 },
  );
  if (injection.exitCode !== 0) {
    throw new Error(`could not inject request into xctestrun (status ${injection.exitCode})`);
  }
  const result = await executeCommand(invocation.argv, {
    cwd: repositoryRoot,
    env: { ...process.env, NSUnbufferedIO: "YES" },
    timeoutMs: 180_000,
  });
  const xcodeOutput = `${result.stdout}\n${result.stderr}`;
  let response;
  try {
    response = extractXCUITestResponse(xcodeOutput);
  } catch (cause) {
    process.stderr.write(`${xcodeOutput.slice(-16_384)}\n`);
    throw cause;
  }
  if (result.exitCode !== 0 && response.ok === true) {
    throw new Error(`xcodebuild failed with status ${result.exitCode}`);
  }
  process.stdout.write(JSON.stringify(response));
} catch (cause) {
  process.stderr.write(`MOOPS XCUITest adapter: ${cause.message}\n`);
  process.exitCode = 1;
} finally {
  if (temporaryXCTestRun !== undefined) {
    await rm(temporaryXCTestRun, { force: true });
  }
}
4. Define `install` as a replacement install. For Simulator apps, the reference
   command is `xcrun simctl install <udid> <app-path>` with no preceding
   `uninstall`.
5. Provide a UI adapter executable that implements protocol v1 below. XCUITest
   is one implementation option; any executable that honors the protocol works.
6. Recompute the checkpoint fingerprint after every edit, then validate it:

   ```sh
   node --input-type=module -e '
   import { readFile, writeFile } from "node:fs/promises";
   import { fingerprintCheckpoint } from "./tools/moops/src/checkpoint.mjs";
   const path = process.argv[1];
   const checkpoint = JSON.parse(await readFile(path, "utf8"));
   checkpoint.fingerprint = fingerprintCheckpoint(checkpoint);
   await writeFile(path, JSON.stringify(checkpoint, null, 2) + "\n");
   ' path/to/my-app.checkpoint.json

   tools/moops/moops checkpoint path/to/my-app.checkpoint.json
   ```

7. Export any variables referenced by the checkpoint and run the workflow:

   ```sh
   export MOOPS_SIMULATOR_UDID=<booted-simulator-udid>
   export MOOPS_DERIVED_DATA=<TMP>/my-app-derived-data

   tools/moops/moops doctor path/to/my-app.checkpoint.json
   tools/moops/moops build-and-restore path/to/my-app.checkpoint.json \
     --output results/my-app-restore.json
   ```

The fingerprint detects checkpoint drift; it is not a signature. A checkpoint
declares executable commands, so only run checkpoints from repositories you
trust.

## Checkpoint contract

Schema version 1 requires exactly these top-level fields:

| Field | Contract |
| --- | --- |
| `schemaVersion` | Must be `1`. |
| `fixtureVersion` | Integration-controlled nonempty revision included in reports; update it when fixture assumptions change. |
| `name` | Nonempty checkpoint name reported by the CLI. |
| `app.bundleId` | Target application bundle identifier. |
| `simulator.udid` | Target Simulator UDID; environment expansion is allowed. |
| `adapters.doctor` | One to eight prerequisite argv arrays. |
| `adapters.build`, `install`, `launch`, `ui` | One nonempty argv array for each extension point. |
| `trace` | One to 32 `wait` or `tap` steps over public selectors. |
| `landingPredicates` | One to 32 `exists` or `equals` predicates. |
| `fingerprint` | Lowercase `sha256:` digest of the canonical checkpoint payload excluding this field. |

